// Cek Sistem Operasi
var jenisOS:String = Capabilities.os.toLowerCase();

// Variabel youtube
var linkYoutube:String = "";

// Variabel lagu
var channelMusik:SoundChannel = new SoundChannel();
var volumeMusik:SoundTransform = new SoundTransform(0.6); // Volume 60%
var laguSedangMain:String = ""; // Untuk mengingat lagu apa yang sedang main

// Logika IF (Jika Android) dan ELSE (Jika Desktop/Lainnya)
if (jenisOS.indexOf("android") >= 0 || jenisOS.indexOf("iphone") >= 0) {

	// --- KODE KHUSUS HP (ANDROID/iOS) ---
	stage.scaleMode = StageScaleMode.SHOW_ALL;
	stage.align = StageAlign.TOP_LEFT;

} else {

	// --- KODE KHUSUS DESKTOP (PC/LAPTOP) ---
	stage.scaleMode = StageScaleMode.EXACT_FIT;
	stage.align = StageAlign.TOP_LEFT;

	// Otomatis Fullscreen kalau di Laptop/PC
	stage.displayState = StageDisplayState.FULL_SCREEN;
}

//Mengatur Lagu
function putarLagu(KelasLagu:Class, namaLagu:String):void {
	if(laguSedangMain == namaLagu) return;

	// Kalau beda, matikan lagu lama
	SoundMixer.stopAll();

	// Mainkan lagu baru
	var lagu:Sound = new KelasLagu() as Sound;
	channelMusik = lagu.play(0, 9999); // Looping 9999
	channelMusik.soundTransform = volumeMusik;

	// Catat nama lagu baru
	laguSedangMain = namaLagu;
}

function stopMusik():void {
	SoundMixer.stopAll();
	laguSedangMain = "";
}

