// Variabel Game
var skor:int = 0;
var indexSoal:int = 0;
var totalSoal:int = bankSoal.length;
var frameTujuan:int = 20;
var sedangMenjawab:Boolean = false;

// --- INIT ---
initGame();

function initGame():void {
	skor = 0;
	indexSoal = 0;

	// Kita panggil fungsi pengacak sebelum kuis dimulai
	acakArray(bankSoal);

	// Setup text
	if(getChildByName("txt_soal")) { 
		Object(getChildByName("txt_soal")).wordWrap = true; 
		Object(getChildByName("txt_soal")).multiline = true;
	}
	if(getChildByName("txt_skor")) Object(getChildByName("txt_skor")).autoSize = TextFieldAutoSize.RIGHT;
	if(getChildByName("txt_progress")) Object(getChildByName("txt_progress")).autoSize = TextFieldAutoSize.LEFT;

	// Setup Tombol
	for(var i:int = 0; i < 4; i++){
		var btn:MovieClip = getChildByName("btn_jawab" + i) as MovieClip;
		if(btn){
			btn.id = i; 
			btn.buttonMode = true; 
			btn.mouseChildren = false; 
			if(btn.hasEventListener(MouseEvent.CLICK)) btn.removeEventListener(MouseEvent.CLICK, cekJawaban);
			btn.addEventListener(MouseEvent.CLICK, cekJawaban);
		}
	}
	tampilkanSoal();
}

// Fungsi ini akan mengocok posisi soal seperti mengocok kartu
function acakArray(inputArray:Array):void {
	var i:int = inputArray.length;
	var j:int;
	var temp:Object;

	while ( --i > 0 ) {
		j = Math.floor( Math.random() * ( i + 1 ) );
		temp = inputArray[i];
		inputArray[i] = inputArray[j];
		inputArray[j] = temp;
	}
}

function tampilkanSoal():void {
	if(indexSoal >= totalSoal){
		pergiKeHasil();
		return;
	}

	sedangMenjawab = false;
	var data:Object = bankSoal[indexSoal];

	// Update Soal & Skor
	if(getChildByName("txt_soal")) Object(getChildByName("txt_soal")).text = data.t;
	if(getChildByName("txt_skor")) Object(getChildByName("txt_skor")).text = "Skor: " + skor;
	if(getChildByName("txt_progress")) Object(getChildByName("txt_progress")).text = "Pertanyaan " + (indexSoal + 1) + "/" + totalSoal;
	if(getChildByName("bar_time")) Object(getChildByName("bar_time")).scaleX = (indexSoal + 1) / totalSoal;

	// Update Tombol
	for(var i:int = 0; i < 4; i++){
		var btn:MovieClip = getChildByName("btn_jawab" + i) as MovieClip;
		if(btn){
			btn.gotoAndStop(1); 
			if(btn.getChildByName("txt_label")){
				Object(btn.getChildByName("txt_label")).text = data.j[i];
			}
		}
	}
}

function cekJawaban(e:MouseEvent):void {
	if(sedangMenjawab) return;
	sedangMenjawab = true;

	var btnKlik:MovieClip = e.currentTarget as MovieClip;
	var jawabanUser:int = btnKlik.id;
	var kunci:int = bankSoal[indexSoal].b;

	if(jawabanUser == kunci){
		skor += 10; // 10 Poin per soal (Total 100)
		btnKlik.gotoAndStop(2);
	} else {
		btnKlik.gotoAndStop(3);
		var btnBenar:MovieClip = getChildByName("btn_jawab" + kunci) as MovieClip;
		if(btnBenar) btnBenar.gotoAndStop(2);
	}

	if(getChildByName("txt_skor")) Object(getChildByName("txt_skor")).text = "Skor: " + skor;
	setTimeout(nextSoal, 1500);
}

function nextSoal():void {
	indexSoal++;
	tampilkanSoal();
}

function pergiKeHasil():void {
	MovieClip(root).skorFinal = skor;

	// Bersihkan listener
	for(var i:int = 0; i < 4; i++){
		var btn:MovieClip = getChildByName("btn_jawab" + i) as MovieClip;
		if(btn && btn.hasEventListener(MouseEvent.CLICK)) {
			btn.removeEventListener(MouseEvent.CLICK, cekJawaban);
		}
	}
	gotoAndStop(frameTujuan);
}

