import flash.events.Event;

// Hentikan timeline agar tidak auto-play
stop();

// Panggil lagu Materi
putarLagu(bgm_baca1, "baca1");

// Membaca link yang tadi diset di Menu
if(getChildByName("btn_play1")) {
    // Bersihkan listener lama
    if(btn_play1.hasEventListener(MouseEvent.CLICK)) btn_play1.removeEventListener(MouseEvent.CLICK, bukaYoutube);

    // Pasang listener baru
    btn_play1.addEventListener(MouseEvent.CLICK, bukaYoutube);
}

function bukaYoutube(e:MouseEvent):void {
	stopMusik();

    // Cek dulu apakah linknya ada isinya?
    if(linkYoutube != "") {
        var request:URLRequest = new URLRequest(linkYoutube);
        navigateToURL(request, "_blank");
    } else {
        trace("Link Youtube belum diisi!");
    }
}

