// Variabel penampung (untuk mengingat mau ke halaman berapa)
var halamanTujuan:int = 0;

// Fungsi yang dipanggil oleh TOMBOL (Buat memicu animasi)
function gantiHalaman(frameKe:int):void {
    halamanTujuan = frameKe; // Catat tujuannya
    mc_awalberanda.gotoAndPlay(2); // Jalankan animasi
}

function pindahSekarang():void {
    gotoAndStop(halamanTujuan); // Pindah beneran
}

btn_layar1.addEventListener(MouseEvent.CLICK, changeAwalBeranda);
function changeAwalBeranda(e:MouseEvent):void{
	gantiHalaman(2);
}
